  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val RequestQualification_supervisionProcess_requestQualification_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_requestQualification.id
    val DockingAssessmentOwner_supervisionProcess_dockingAssessmentOwner_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_dockingAssessmentOwner.id
    val ShipProgressQualification_supervisionProcess_shipProgressQualification_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_shipProgressQualification.id
    val WarehouseEvidenceQualification_supervisionProcess_warehouseEvidenceQualification_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_warehouseEvidenceQualification.id
    val TransferDecisionOwner_supervisionProcess_transferDecisionOwner_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_transferDecisionOwner.id
    val TransferCommandDerivation_supervisionProcess_transferCommandDerivation_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_transferCommandDerivation.id
    val TransferReportDerivation_supervisionProcess_transferReportDerivation_id = Arch.MiningCargoTransferSupervisorSystem_Instance_supervisionProcess_transferReportDerivation.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case RequestQualification_supervisionProcess_requestQualification_id =>
          val prefix = "RequestQualification_supervisionProcess_requestQualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Cargo_Transfer_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Mining_Cargo_Transfer_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Mining_Cargo_Transfer_Supervisor._
                |
                |class ${suiteName} extends RequestQualification_supervisionProcess_requestQualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case DockingAssessmentOwner_supervisionProcess_dockingAssessmentOwner_id =>
          val prefix = "DockingAssessmentOwner_supervisionProcess_dockingAssessmentOwner_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Cargo_Transfer_Supervisor")
